function validateImportedBackup(data){
 if(!data||typeof data!=='object'||Array.isArray(data))return 'O arquivo não contém um objeto de backup válido.';
 const schemas={edits:'object',lexicalNotes:'object',guides:'array',studyEdits:'object',symbols:'array',characters:'array',bookInfoEdits:'object',studyCategories:'object',editorialReviews:'object'};
 const present=Object.keys(schemas).filter(k=>Object.prototype.hasOwnProperty.call(data,k));
 if(!present.length)return 'O arquivo não contém campos reconhecidos da Enciclopédia Bíblica.';
 const stringFields={
  lexicalNotes:['term','text'],
  edits:['title','summary','explanation','versesText','episodes','refs','characterDetailsText','symbolDetailsText'],
  guides:['name','description','content'],
  studyEdits:['name','category','description'],
  symbols:['name','mark','text','refs'],
  characters:['name','bio','refs'],
  bookInfoEdits:['intro','note'],
  studyCategories:['title','description'],
  editorialReviews:[]
 };
 for(const field of present){
  const value=data[field],kind=schemas[field];
  if(kind==='array'&&!Array.isArray(value))return 'O campo '+field+' deveria ser uma lista.';
  if(kind==='object'&&(!value||typeof value!=='object'||Array.isArray(value)))return 'O campo '+field+' deveria ser um objeto.';
  const records=kind==='array'?value:Object.values(value);
  if(records.some(item=>!item||typeof item!=='object'||Array.isArray(item)))return 'O campo '+field+' contém registros inválidos.';
  for(const item of records){
   for(const property of stringFields[field]){
    if(Object.prototype.hasOwnProperty.call(item,property)&&typeof item[property]!=='string')
     return 'O campo '+field+' contém um valor inválido em '+property+'.';
   }
  }
 }
 if(data.editorialReviews){
  const allowedStates=['pendente','em_revisao','revisado','reaberto'];
  for(const [key,record] of Object.entries(data.editorialReviews)){
   if(!/^\d+-\d+-\d+$/.test(key)||!record||typeof record!=='object'||Array.isArray(record)||!allowedStates.includes(record.status))return 'O registro editorial contém uma chave ou estado inválido.';
   if(record.history!==undefined&&(!Array.isArray(record.history)||record.history.some(event=>!event||typeof event!=='object'||Array.isArray(event)||!allowedStates.includes(event.to))))return 'O histórico editorial contém movimentações inválidas.';
   for(const field of ['source','observation','reopenReason','updatedAt'])if(record[field]!==undefined&&typeof record[field]!=='string')return 'O registro editorial contém um campo inválido: '+field+'.';
  }
 }
 for(const field of ['guides','symbols','characters']){
  if(data[field]&&data[field].some(item=>typeof item.name!=='string'||!item.name.trim()))
   return 'Há um registro sem nome válido em '+field+'.';
 }
 return '';
}
$('importData').onchange=async e=>{
 const file=e.target.files&&e.target.files[0];if(!file)return;
 try{
  if(file.size>15*1024*1024)throw new Error('O arquivo excede o limite de 15 MB.');
  const data=JSON.parse(await file.text()),problem=validateImportedBackup(data);
  if(problem)throw new Error(problem);
  const oldEdits=edits,previous={};
  [...BACKUP_KEYS,AUTO_BACKUP_KEY,AUTO_BACKUP_HISTORY_KEY].forEach((storageKey)=>previous[storageKey]=localStorage.getItem(storageKey));
  try{
   if(Object.prototype.hasOwnProperty.call(data,'edits')){edits=data.edits;localStorage.setItem(key,JSON.stringify(edits))}
   if(Object.prototype.hasOwnProperty.call(data,'lexicalNotes'))localStorage.setItem('encBibLexicalNotesV1',JSON.stringify(data.lexicalNotes));
   for(const [field,storageKey] of [['guides','encBibGuides'],['studyEdits','encBibStudyEdits'],['symbols','encBibSymbols'],['characters','encBibCharacters'],['bookInfoEdits',BOOK_INFO_EDITS_KEY],['studyCategories',STUDY_CATEGORIES_KEY],['editorialReviews','encBibEditorialReviewsV1']]){
    if(Object.prototype.hasOwnProperty.call(data,field))localStorage.setItem(storageKey,JSON.stringify(data[field]));
   }
   const backupData={};
   BACKUP_KEYS.forEach(storageKey=>{const saved=localStorage.getItem(storageKey);if(saved!==null)backupData[storageKey]=saved});
   const snapshot={savedAt:new Date().toISOString(),data:backupData};
   localStorage.setItem(AUTO_BACKUP_KEY,JSON.stringify(snapshot));
   const history=readLocalData(AUTO_BACKUP_HISTORY_KEY,[]);
   history.unshift(snapshot);
   localStorage.setItem(AUTO_BACKUP_HISTORY_KEY,JSON.stringify(history.slice(0,8)));
  }catch(storageError){
   edits=oldEdits;
   [...BACKUP_KEYS,AUTO_BACKUP_KEY,AUTO_BACKUP_HISTORY_KEY].forEach(storageKey=>{if(previous[storageKey]===null)localStorage.removeItem(storageKey);else localStorage.setItem(storageKey,previous[storageKey])});
   throw storageError;
  }
  renderGuides();renderSymbols();renderCharacters();renderStudyCategorySettings();fillBookInfoEditor();loadEdit();if(window.refreshEditorialReviewPanel)window.refreshEditorialReviewPanel();
  $('saveStatus').textContent='Backup importado e validado. Campos ausentes foram mantidos como estavam.';
 }catch(error){
  const message=error&&error.message?error.message:'Não foi possível ler esse arquivo de backup.';
  $('saveStatus').textContent='Importação não realizada: '+message;
  alert('Backup não importado: '+message);
 }finally{e.target.value=''}
}
$('clearData').onclick=()=>{
 if(!confirm('Apagar todas as edições, guias, símbolos, personagens e alterações locais do registro editorial salvos neste navegador? Essa ação também apaga os backups automáticos locais. Os estados-base versionados no repositório permanecem. Exporte uma cópia antes, se quiser guardá-la.'))return;
 try{
  [...BACKUP_KEYS,AUTO_BACKUP_KEY,AUTO_BACKUP_HISTORY_KEY].forEach(storageKey=>localStorage.removeItem(storageKey));
  edits={};renderGuides();renderSymbols();renderCharacters();renderStudyCategorySettings();fillBookInfoEditor();loadEdit();
  if(window.refreshEditorialReviewPanel)window.refreshEditorialReviewPanel();$('saveStatus').textContent='Dados locais apagados. O histórico de backups automáticos também foi removido; estados-base do repositório permanecem.';
 }catch(error){
  recordAppError(error,'Falha ao limpar dados locais');
  $('saveStatus').textContent='Não foi possível concluir a limpeza dos dados locais. Verifique as permissões de armazenamento do navegador.';
 }
};
function fillBookInfoEditor(){
 const index=+$('bookInfoBook').value,data=getBookInfoData(index);
 if(!data){$('bookInfoIntro').value='';$('bookInfoFields').value='';$('bookInfoNote').value='';return}
 $('bookInfoIntro').value=data.intro||'';
 $('bookInfoFields').value=(data.fields||[]).map(([label,value])=>label+' | '+value).join('\n');
 $('bookInfoNote').value=data.note||'';
 $('bookInfoStatus').textContent='Ficha carregada: '+BOOKS[index].name+'.';
}
BOOKS.forEach((book,index)=>$('bookInfoBook').add(new Option(book.name,index)));
$('bookInfoBook').onchange=fillBookInfoEditor;
$('saveBookInfo').onclick=()=>{
 const index=+$('bookInfoBook').value,intro=$('bookInfoIntro').value.trim(),note=$('bookInfoNote').value.trim(),lines=$('bookInfoFields').value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean),fields=[];
 for(let i=0;i<lines.length;i++){
  const split=lines[i].indexOf('|');
  if(split<1||!lines[i].slice(split+1).trim()){$('bookInfoStatus').textContent='Revise a linha '+(i+1)+': use Título | Texto.';return}
  fields.push([lines[i].slice(0,split).trim(),lines[i].slice(split+1).trim()]);
 }
 if(!intro||!note||!fields.length){$('bookInfoStatus').textContent='Preencha introdução, pelo menos um tópico e nota final.';return}
 const overrides=readLocalObject(BOOK_INFO_EDITS_KEY);overrides[index]={intro,fields,note};
 const result=saveLocalData(BOOK_INFO_EDITS_KEY,JSON.stringify(overrides));
 $('bookInfoStatus').textContent=!result.saved?'Não foi possível salvar. Verifique o espaço disponível no navegador.':!result.backedUp?'Ficha salva, mas o backup automático falhou. Exporte uma cópia manual.':'Ficha de '+BOOKS[index].name+' salva neste navegador e incluída no backup automático local.';
 if(result.saved&&currentBook===index)renderBook();
};
$('resetBookInfo').onclick=()=>{
 const index=+$('bookInfoBook').value;
 if(!confirm('Restaurar a ficha padrão de '+BOOKS[index].name+'? Suas alterações locais dessa ficha serão removidas.'))return;
 const overrides=readLocalObject(BOOK_INFO_EDITS_KEY);delete overrides[index];
 const result=saveLocalData(BOOK_INFO_EDITS_KEY,JSON.stringify(overrides));
 fillBookInfoEditor();$('bookInfoStatus').textContent=result.saved?'Ficha padrão restaurada para '+BOOKS[index].name+'.':'Não foi possível restaurar a ficha.';
 if(currentBook===index)renderBook();
};
fillBookInfoEditor();
document.querySelectorAll('.navbtn,.bottom-tab').forEach(b=>b.onclick=()=>show(b.dataset.view));$('backBooks').onclick=()=>show('home');
$('saveStudyCategories').onclick=saveStudyCategorySettings;
$('resetStudyCategories').onclick=()=>{if(!confirm('Restaurar os nomes e descrições padrão das abas?'))return;const result=saveLocalData(STUDY_CATEGORIES_KEY,JSON.stringify({}));$('studyCategoriesStatus').textContent=result.saved?'Nomes e descrições padrão restaurados.':'Não foi possível restaurar as abas.';renderStudyCategorySettings();};
renderBooks();renderGuides();renderStudyCategorySettings();renderSymbols();renderCharacters();